namespace leveldb {
namespace crc32c {

static const uint32_t kMaskDelta = 0xa282ead8ul;

inline uint32_t Mask(uint32_t crc) {
    return ((crc >> 15) | (crc << 17)) + kMaskDelta;
}

} // namespace crc32c
} // namespace leveldb
